std::vector<std::pair<int, int>> free_slots(int limit, std::vector<std::pair<int, int>> busy) {
    if (limit <= 0) return {};

    std::vector<std::pair<int, int>> free;
    for (const auto& interval : busy) {
        if (interval.first < 0 || interval.second > limit || interval.first >= interval.second) continue;
        if (free.empty() || free.back().second < interval.first) free.push_back(interval);
        else free.back().second = std::max(free.back().second, interval.second);
    }

    std::vector<std::pair<int, int>> merged;
    for (const auto& interval : free) {
        if (merged.empty() || merged.back().second < interval.first) merged.push_back(interval);
        else merged.back().second = std::max(merged.back().second, interval.second);
    }

    return merged;
}

int main() {
    std::vector<std::pair<int, int>> busy = {{1, 3}, {5, 7}, {10, 12}};
    auto free = free_slots(10, busy);
    for (const auto& interval : free) {
        std::cout << "[" << interval.first << ", " << interval.second << ")\n";
    }
    return 0;
}

