    for (int i = 0; i < n; ++i) {
        prefix_sum[i + 1] = prefix_sum[i] + values[i];
    }

    int min_span = n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            if (prefix_sum[j + 1] - prefix_sum[i] >= threshold) {
                min_span = std::min(min_span, j - i + 1);
                break;
            }
        }
    }

    return min_span == n + 1 ? 0 : min_span;
}

