#include <vector>
#include <unordered_map>
#include <queue>
#include <algorithm>

std::vector<std::vector<int>> build_layers(int n, const std::vector<std::pair<int,int>>& prerequisites) {
    std::vector<std::vector<int>> layers;
    std::unordered_map<int, std::vector<int>> graph;
    std::unordered_map<int, int> in_degree;
    std::queue<int> q;

    // Build the graph and in-degree map
    for (const auto& p : prerequisites) {
        graph[p.first].push_back(p.second);
        in_degree[p.second]++;
    }

    // Find all nodes with in-degree 0
    for (int i = 0; i < n; ++i) {
        if (in_degree[i] == 0) {
            q.push(i);
        }
    }

    // Perform topological sort
    while (!q.empty()) {
        int current = q.front();
        q.pop();
        layers.push_back({current});

        for (int neighbor : graph[current]) {
            in_degree[neighbor]--;
            if (in_degree[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }

    // Check if there is a cycle
    if (layers.size() != n) {
        return {};
    }

    return layers;
}

int main() {
    // Example usage
    std::vector<std::pair<int, int>> prerequisites = {{1, 0}, {2, 0}, {3, 1}, {4, 2}};
    int n = 4;
    std::vector<std::vector<int>> result = build_layers(n, prerequisites);
    for (const auto& layer : result) {
        for (int task : layer) {
            std::cout << task << " ";
        }
        std::cout << std::endl;
    }
    return 0;
}

#include <vector>
