#include <algorithm>
#include <map>
#include <set>
#include <cassert>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    if (k <= 0) return {};

    std::map<std::string, int> word_counts;
    for (const auto& word : words) {
        ++word_counts[word];
    }

    std::multiset<std::pair<int, std::string>, std::greater<std::pair<int, std::string>>> sorted_words;
    for (const auto& pair : word_counts) {
        sorted_words.insert({pair.second, pair.first});
    }

    std::vector<std::string> result;
    for (int i = 0; i < k && !sorted_words.empty(); ++i) {
        result.push_back(sorted_words.begin()->second);
        sorted_words.erase(sorted_words.begin());
    }

    return result;
}

int main() {
    assert(top_words({}, 3) == std::vector<std::string>());
    assert(top_words({"apple", "banana", "apple", "orange", "banana", "apple"}, 2) == std::vector<std::string>{"apple", "banana"});
    assert(top_words({"hello", "world", "hello", "cpp", "world", "cpp"}, 3) == std::vector<std::string>{"cpp", "hello", "world"});
    assert(top_words({"a", "b", "c", "d", "e"}, 1) == std::vector<std::string>{"e"});
    assert(top_words({"a", "b", "c", "d", "e"}, 0) == std::vector<std::string>());
    assert(top_words({"a", "a", "a", "a", "a"}, 3) == std::vector<std::string>{"a"});

    return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <cassert>

int main() {
    std::unordered_map<std::string, int> inventory;
    std::string command;

    while (std::getline(std::cin, command)) {
        if (command == "PUT name") {
            std::string name;
            std::cin >> name;
            if (inventory.find(name) == inventory.end()) {
                inventory[name] = 0;
            }
            inventory[name]++;
        } else if (command == "TAKE name") {
            std::string name;
            std::cin >> name;
            if (inventory.find(name) != inventory.end() && inventory[name] > 0) {
                inventory[name]--;
            }
        } else if (command == "QUERY name") {
            std::string name;
            std::cin >> name;
            if (inventory.find(name) != inventory.end()) {
                std::cout << inventory[name] << std::endl;
            }
        }
    }

    return 0;
}

